/* Thermal illustrations and documented endpoint comparisons; no synthetic time series. */
'use strict';
const dir='assets/diagrams/thermal/';
const captions={ko:'대기·적설·A/B/C/D 토양층·1D 하천을 연결하는 열전도와 물의 현열수송 개념입니다.',en:'Conduction and water-borne sensible heat connect atmosphere, snow, A/B/C/D soil layers and a 1D river.'};
function asset(lang,pre=''){return {src:pre+dir+'thermal-process-'+lang+'.svg',width:1200,height:720,caption:captions[lang],shared:false};}
function results(lang,pre=''){
 const ko=lang==='ko',L=(k,e)=>ko?k:e;
 const figures=[['soil-response',L('토양층별 반응: 깊은 층의 변화는 작습니다','Soil response: deeper layers change less'),L('12시간 말 고온 조건−기준 조건. 동일 토양격자의 A/B/C/D층 온도 차이입니다.','Warm minus baseline at 12 h: temperature differences in A/B/C/D at one soil cell.')],['river-response',L('하천수온도 기온 변화에 반응합니다','River temperature responds to air forcing'),L('같은 시험의 12시간 말 수온 차이입니다. 한 하천격자의 값과 548개 젖은 하천격자의 산술평균은 서로 다른 공간 통계입니다.','Endpoint differences from the same trial: a single river cell and the arithmetic mean of 548 wet river cells are different spatial statistics.')]];
 return `<div class="thermal-evidence"><h4>${L('섬진강 시험유역 · 실제 계산 결과','Seomjin trial basin · actual model output')}</h4><p>${L('기준 조건에 비해 본모의 기온과 이슬점을 함께 15°C 높인 민감도 시험입니다. 2020-07-29 00:00–12:00의 12시간을 계산했습니다. 첫 기상 기록은 유지하고 이후 기록을 바꿨으며, 관측 정확도 평가가 아닌 반응 확인 시험입니다.','Sensitivity trial raising production air temperature and dewpoint together by 15°C relative to baseline. The 12-hour window is 00:00–12:00 on 29 July 2020. The first meteorological record was preserved and later records shifted. This checks response, not agreement with observed temperatures.')}</p>${figures.map(([name,title,caption])=>{const src=pre+dir+name+'-'+lang+'.svg';return `<figure class="figure result-example"><h4>${title}</h4><a href="${src}" data-enlarge data-caption="${caption}"><img src="${src}" alt="${caption}" width="1200" height="720" loading="lazy" decoding="async"></a><figcaption><small>${caption}</small><a href="${src}" data-enlarge data-caption="${caption}">${L('확대해서 보기 ↗','Enlarge ↗')}</a></figcaption></figure>`;}).join('')}<p class="small">${L('막대는 실제 시험의 종료시점 차이이며 시간변화 곡선이 아닙니다. 깊은 층의 단기 반응이 작다는 결과만으로 장기 수온 정확도를 판단하지 않습니다.','Bars are actual endpoint differences, not a time series. A small short-term deep-layer response does not establish long-term accuracy.')}</p><p><a href="https://github.com/YoungTeckHUR/KDRUM-Public/blob/main/THERMAL_VALIDATION.md">${L('시험조건·수치·적용 범위','Trial conditions, values and scope')} ↗</a></p></div>`;
}
module.exports={asset,results};
